  1→package jlsm.table;
  2→
  3→import java.util.List;
  4→import java.util.Objects;
  5→
  6→/**
  7→ * A query predicate AST node. Predicates form a tree that the query executor inspects to select
  8→ * indices and build execution plans.
  9→ *
 10→ * <p>
 11→ * Designed to be inspectable and serializable for future SQL translation.
 12→ *
 13→ * <p>
 14→ * Contract:
 15→ * <ul>
 16→ * <li>All leaf predicates carry a field name and typed value(s)</li>
 17→ * <li>Composite predicates (And, Or) hold a list of child predicates</li>
 18→ * <li>Field name and type compatibility validated eagerly at construction</li>
 19→ * </ul>
 20→ */
 21→public sealed interface Predicate {
 22→
 23→    /** Equality: field == value. Usable with any primitive field type. */
 24→    record Eq(String field, Object value) implements Predicate {
 25→        public Eq {
 26→            Objects.requireNonNull(field);
 27→            Objects.requireNonNull(value);
 28→        }
 29→    }
 30→
 31→    /** Inequality: field != value. Usable with any primitive field type. */
 32→    record Ne(String field, Object value) implements Predicate {
 33→        public Ne {
 34→            Objects.requireNonNull(field);
 35→            Objects.requireNonNull(value);
 36→        }
 37→    }
 38→
 39→    /** Greater than: field > value. Requires an ordered field type. */
 40→    record Gt(String field, Comparable<?> value) implements Predicate {
 41→        public Gt {
 42→            Objects.requireNonNull(field);
 43→            Objects.requireNonNull(value);
 44→        }
 45→    }
 46→
 47→    /** Greater than or equal: field >= value. Requires an ordered field type. */
 48→    record Gte(String field, Comparable<?> value) implements Predicate {
 49→        public Gte {
 50→            Objects.requireNonNull(field);
 51→            Objects.requireNonNull(value);
 52→        }
 53→    }
 54→
 55→    /** Less than: field < value. Requires an ordered field type. */
 56→    record Lt(String field, Comparable<?> value) implements Predicate {
 57→        public Lt {
 58→            Objects.requireNonNull(field);
 59→            Objects.requireNonNull(value);
 60→        }
 61→    }
 62→
 63→    /** Less than or equal: field <= value. Requires an ordered field type. */
 64→    record Lte(String field, Comparable<?> value) implements Predicate {
 65→        public Lte {
 66→            Objects.requireNonNull(field);
 67→            Objects.requireNonNull(value);
 68→        }
 69→    }
 70→
 71→    /** Range: low <= field <= high. Requires an ordered field type. */
 72→    record Between(String field, Comparable<?> low, Comparable<?> high) implements Predicate {
 73→        public Between {
 74→            Objects.requireNonNull(field);
 75→            Objects.requireNonNull(low);
 76→            Objects.requireNonNull(high);
 77→        }
 78→    }
 79→
 80→    /**
 81→     * Full-text match: field contains the query terms. Requires a STRING field with FULL_TEXT
 82→     * index.
 83→     */
 84→    record FullTextMatch(String field, String query) implements Predicate {
 85→        public FullTextMatch {
 86→            Objects.requireNonNull(field);
 87→            Objects.requireNonNull(query);
 88→        }
 89→    }
 90→
 91→    /**
 92→     * Vector nearest neighbour: find the topK closest vectors to the query. Requires a VECTOR
 93→     * index.
 94→     */
 95→    record VectorNearest(String field, float[] queryVector, int topK) implements Predicate {
 96→        public VectorNearest {
 97→            Objects.requireNonNull(field);
 98→            Objects.requireNonNull(queryVector);
 99→            if (topK <= 0) {
100→                throw new IllegalArgumentException("topK must be positive");
101→            }
102→        }
103→    }
104→
105→    /** Logical AND: all children must match. */
106→    record And(List<Predicate> children) implements Predicate {
107→        public And {
108→            Objects.requireNonNull(children);
109→            if (children.size() < 2) {
110→                throw new IllegalArgumentException("And requires at least 2 children");
111→            }
112→            children = List.copyOf(children);
113→        }
114→    }
115→
116→    /** Logical OR: at least one child must match. */
117→    record Or(List<Predicate> children) implements Predicate {
118→        public Or {
119→            Objects.requireNonNull(children);
120→            if (children.size() < 2) {
121→                throw new IllegalArgumentException("Or requires at least 2 children");
122→            }
123→            children = List.copyOf(children);
124→        }
125→    }
126→}
