  3→/**
  4→ * Utility class for converting between IEEE 754 single-precision (float) and half-precision
  5→ * (float16) bit representations.
  6→ *
  7→ * <p>
  8→ * Half-precision format: 1 sign bit, 5 exponent bits (bias 15), 10 mantissa bits. Single-precision
  9→ * format: 1 sign bit, 8 exponent bits (bias 127), 23 mantissa bits.
 10→ *
 11→ * <p>
 12→ * Handles all special cases: ±0, ±infinity, NaN, and subnormals in both directions.
 13→ */
 14→public final class Float16 {
 15→
 16→    // Half-precision constants
 17→    private static final int HALF_SIGN_MASK = 0x8000;
 18→    private static final int HALF_EXP_MASK = 0x7C00;
 19→    private static final int HALF_MANTISSA_MASK = 0x03FF;
 20→    private static final int HALF_EXP_BIAS = 15;
 21→    private static final int HALF_EXP_MAX = 31; // all ones = infinity/NaN
 22→
 23→    // Single-precision constants
 24→    private static final int FLOAT_EXP_MASK = 0x7F800000;
 25→    private static final int FLOAT_MANTISSA_MASK = 0x007FFFFF;
 26→    private static final int FLOAT_EXP_BIAS = 127;
 27→
 28→    private Float16() {
 29→    }
 30→
 31→    /**
 32→     * Converts a single-precision float to a half-precision bit pattern.
 33→     *
 34→     * <p>
 35→     * The returned {@code short} contains the IEEE 754 half-precision bits. Overflow (too large for
 36→     * float16) maps to ±infinity. Values too small for normal half-precision map to subnormals or
 37→     * zero.
 38→     *
 39→     * @param f the float to convert
 40→     * @return the half-precision bit pattern as a {@code short}
 41→     */
 42→    public static short fromFloat(float f) {
 43→        final int floatBits = Float.floatToRawIntBits(f);
 44→
 45→        final int sign = (floatBits >>> 16) & HALF_SIGN_MASK;
 46→        final int floatExp = (floatBits & FLOAT_EXP_MASK) >>> 23;
 47→        final int floatMantissa = floatBits & FLOAT_MANTISSA_MASK;
 48→
 49→        // NaN or Infinity
 50→        if (floatExp == 0xFF) {
 51→            if (floatMantissa != 0) {
 52→                // NaN — preserve a non-zero mantissa (but cap to half precision)
 53→                return (short) (sign | HALF_EXP_MASK | 0x0001);
 54→            } else {
 55→                // ±Infinity
 56→                return (short) (sign | HALF_EXP_MASK);
 57→            }
 58→        }
 59→
 60→        // Zero (positive or negative)
 61→        if (floatExp == 0 && floatMantissa == 0) {
 62→            return (short) sign;
 63→        }
 64→
 65→        // Compute half exponent (unbiased: floatExp - FLOAT_EXP_BIAS, then re-biased)
 66→        final int halfExp = floatExp - FLOAT_EXP_BIAS + HALF_EXP_BIAS;
 67→
 68→        if (halfExp >= HALF_EXP_MAX) {
 69→            // Overflow → ±infinity
 70→            return (short) (sign | HALF_EXP_MASK);
 71→        }
 72→
 73→        if (halfExp <= 0) {
 74→            // Result is subnormal in half-precision (or underflows to zero)
 75→            // The implicit leading 1 must be shifted into the mantissa
 76→            // halfExp of 0 means the float value fits as the least significant subnormal
 77→            // shift = 1 - halfExp (number of right-shifts needed)
 78→            final int shift = 1 - halfExp;
 79→            if (shift >= 11) {
 80→                // Completely underflows to zero (shift >= 11 means all mantissa bits lost)
 81→                return (short) sign;
 82→            }
 83→            // Form the full 11-bit mantissa (implicit 1 + 10 explicit bits), then shift right
 84→            final int mantissa = (floatMantissa | 0x00800000) >>> (13 + shift);
 85→            assert mantissa <= HALF_MANTISSA_MASK : "subnormal mantissa overflow";
 86→            return (short) (sign | mantissa);
 87→        }
 88→
 89→        // Normal half-precision: round-to-nearest-even
 90→        // The lower 13 bits of the float mantissa are lost; bit 12 is the round bit
 91→        final int halfMantissa = floatMantissa >>> 13;
 92→        final int roundBit = (floatMantissa >>> 12) & 1;
 93→        final int stickyBits = floatMantissa & 0x00000FFF;
 94→        // Round up if: round bit set AND (sticky bits set OR LSB of half mantissa is 1)
 95→        final int roundUp = roundBit & (stickyBits != 0 ? 1 : (halfMantissa & 1));
 96→        int rounded = halfMantissa + roundUp;
 97→        int halfExpFinal = halfExp;
 98→        // Handle mantissa overflow (e.g. 0x3FF + 1 = 0x400)
 99→        if (rounded > HALF_MANTISSA_MASK) {
100→            rounded = 0;
101→            halfExpFinal++;
102→            if (halfExpFinal >= HALF_EXP_MAX) {
103→                // Overflow to infinity
104→                return (short) (sign | HALF_EXP_MASK);
105→            }
106→        }
107→        assert halfExpFinal > 0 && halfExpFinal < HALF_EXP_MAX
108→                : "half exponent out of normal range";
109→        return (short) (sign | (halfExpFinal << 10) | rounded);
110→    }
111→
112→    /**
113→     * Converts a half-precision bit pattern to a single-precision float.
114→     *
115→     * @param bits the half-precision bit pattern
116→     * @return the equivalent single-precision float
117→     */
118→    public static float toFloat(short bits) {
119→        final int halfBits = bits & 0xFFFF; // treat as unsigned 16-bit
120→
121→        final int sign = (halfBits & HALF_SIGN_MASK) << 16;
122→        final int halfExp = (halfBits & HALF_EXP_MASK) >>> 10;
123→        final int halfMantissa = halfBits & HALF_MANTISSA_MASK;
124→
125→        if (halfExp == HALF_EXP_MAX) {
126→            // NaN or Infinity
127→            if (halfMantissa != 0) {
128→                // NaN — set high mantissa bit to keep it a quiet NaN
129→                return Float.intBitsToFloat(sign | FLOAT_EXP_MASK | (halfMantissa << 13));
130→            } else {
131→                // ±Infinity
132→                return Float.intBitsToFloat(sign | FLOAT_EXP_MASK);
133→            }
134→        }
135→
136→        if (halfExp == 0) {
137→            if (halfMantissa == 0) {
138→                // ±Zero
139→                return Float.intBitsToFloat(sign);
140→            }
141→            // Subnormal half-precision → normal single-precision
142→            // Find the leading 1 bit position in the 10-bit mantissa.
143→            // Initial floatExp = FLOAT_EXP_BIAS - HALF_EXP_BIAS + 1 = 113: the +1 accounts
144→            // for the fact that the half subnormal mantissa is effectively an integer * 2^-10
145→            // and we need to absorb the implicit leading 1 into the exponent.
146→            int mantissa = halfMantissa;
147→            int floatExp = FLOAT_EXP_BIAS - HALF_EXP_BIAS + 1; // = 113
148→            // Normalize: shift mantissa left until implicit 1 is consumed
149→            while ((mantissa & 0x0400) == 0) {
150→                mantissa <<= 1;
151→                floatExp--;
152→            }
153→            // Clear the implicit 1 bit now that we've encoded it in the exponent
154→            mantissa &= HALF_MANTISSA_MASK;
155→            assert floatExp > 0 : "float exponent underflow during subnormal conversion";
156→            return Float.intBitsToFloat(sign | (floatExp << 23) | (mantissa << 13));
157→        }
158→
159→        // Normal half-precision → normal single-precision
160→        final int floatExp = halfExp + FLOAT_EXP_BIAS - HALF_EXP_BIAS; // re-bias
161→        assert floatExp > 0 && floatExp < 0xFF : "float exponent out of normal range";
162→        return Float.intBitsToFloat(sign | (floatExp << 23) | (halfMantissa << 13));
163→    }
164→}
