  1→package jlsm.table;
  2→
  3→import jlsm.core.io.MemorySerializer;
  4→import jdk.incubator.vector.ByteVector;
  5→import jdk.incubator.vector.DoubleVector;
  6→import jdk.incubator.vector.FloatVector;
  7→import jdk.incubator.vector.IntVector;
  8→import jdk.incubator.vector.LongVector;
  9→import jdk.incubator.vector.VectorShuffle;
 10→import jdk.incubator.vector.VectorSpecies;
 11→
 12→import java.lang.foreign.MemorySegment;
 13→import java.lang.foreign.ValueLayout;
 14→import java.nio.charset.StandardCharsets;
 15→import java.util.List;
 16→import java.util.Objects;
 17→
 18→/**
 19→ * Binary serializer for {@link JlsmDocument} values.
 20→ *
 21→ * <p>
 22→ * The binary format consists of a header (schema version, field count, null bitmask, optional
 23→ * boolean bitmask) followed by serialized non-null, non-boolean field values in schema order.
 24→ *
 25→ * <p>
 26→ * Schema versioning: the header stores the write-time field count. On deserialization with a newer
 27→ * schema, only the write-time fields are decoded; additional fields in the current schema are left
 28→ * {@code null}.
 29→ *
 30→ * <p>
 31→ * Contiguous numeric arrays (INT32, INT64, FLOAT32, FLOAT64) use SIMD byte-swap acceleration via
 32→ * {@code jdk.incubator.vector}.
 33→ */
 34→public final class DocumentSerializer {
 35→
 36→    private DocumentSerializer() {
 37→    }
 38→
 39→    /**
 40→     * Returns a {@link MemorySerializer} for {@link JlsmDocument} values conforming to the given
 41→     * schema.
 42→     *
 43→     * @param schema the schema describing the document structure; must not be null
 44→     * @return a MemorySerializer for JlsmDocument
 45→     */
 46→    public static MemorySerializer<JlsmDocument> forSchema(JlsmSchema schema) {
 47→        Objects.requireNonNull(schema, "schema must not be null");
 48→        return new SchemaSerializer(schema);
 49→    }
 50→
 51→    // =========================================================================
 52→    // Implementation
 53→    // =========================================================================
 54→
 55→    /** SIMD species for byte-level operations (used for byte-swap shuffles). */
 56→    private static final VectorSpecies<Byte> BYTE_SPECIES = ByteVector.SPECIES_PREFERRED;
 57→
 58→    /** Byte-swap shuffle for INT32 / FLOAT32 (4-byte elements). */
 59→    private static final VectorShuffle<Byte> BSWAP32;
 60→
 61→    /** Byte-swap shuffle for INT64 / FLOAT64 (8-byte elements). */
 62→    private static final VectorShuffle<Byte> BSWAP64;
 63→
 64→    static {
 65→        final int byteLen = BYTE_SPECIES.length();
 66→        final int[] idx32 = new int[byteLen];
 67→        final int[] idx64 = new int[byteLen];
 68→        for (int i = 0; i + 3 < byteLen; i += 4) {
 69→            idx32[i + 0] = i + 3;
 70→            idx32[i + 1] = i + 2;
 71→            idx32[i + 2] = i + 1;
 72→            idx32[i + 3] = i + 0;
 73→        }
 74→        for (int i = 0; i + 7 < byteLen; i += 8) {
 75→            idx64[i + 0] = i + 7;
 76→            idx64[i + 1] = i + 6;
 77→            idx64[i + 2] = i + 5;
 78→            idx64[i + 3] = i + 4;
 79→            idx64[i + 4] = i + 3;
 80→            idx64[i + 5] = i + 2;
 81→            idx64[i + 6] = i + 1;
 82→            idx64[i + 7] = i + 0;
 83→        }
 84→        BSWAP32 = VectorShuffle.fromArray(BYTE_SPECIES, idx32, 0);
 85→        BSWAP64 = VectorShuffle.fromArray(BYTE_SPECIES, idx64, 0);
 86→    }
 87→
 88→    // -------------------------------------------------------------------------
 89→    // Serializer implementation
 90→    // -------------------------------------------------------------------------
 91→
 92→    private static final class SchemaSerializer implements MemorySerializer<JlsmDocument> {
 93→
 94→        private final JlsmSchema schema;
 95→
 96→        SchemaSerializer(JlsmSchema schema) {
 97→            this.schema = schema;
 98→        }
 99→
100→        @Override
101→        public MemorySegment serialize(JlsmDocument doc) {
102→            Objects.requireNonNull(doc, "doc must not be null");
103→            assert doc.schema() == schema || doc.schema().name().equals(schema.name())
104→                    : "document schema mismatch";
105→
106→            final List<FieldDefinition> fields = schema.fields();
107→            final int fieldCount = fields.size();
108→            final Object[] values = doc.values();
109→
110→            // Count boolean fields
111→            final int boolCount = countBoolFields(fields);
112→
113→            // Header size: 2 (version) + 2 (fieldCount) + ceil(fieldCount/8) (null mask)
114→            // + (boolCount > 0 ? ceil(boolCount/8) : 0) (bool mask)
115→            final int nullMaskBytes = (fieldCount + 7) / 8;
116→            final int boolMaskBytes = boolCount > 0 ? (boolCount + 7) / 8 : 0;
117→            final int headerSize = 2 + 2 + nullMaskBytes + boolMaskBytes;
118→
119→            // Two-pass: measure then encode
120→            final int payloadSize = measureFields(fields, values);
121→            final int totalSize = headerSize + payloadSize;
122→
123→            final byte[] buf = new byte[totalSize];
124→
125→            // Write header
126→            writeShortBE(buf, 0, (short) schema.version());
127→            writeShortBE(buf, 2, (short) fieldCount);
128→            // Null bitmask
129→            buildNullMask(fields, values, buf, 4);
130→            // Boolean bitmask
131→            if (boolCount > 0) {
132→                buildBoolMask(fields, values, buf, 4 + nullMaskBytes);
133→            }
134→
135→            // Write values
136→            final Cursor cursor = new Cursor(buf, headerSize);
137→            encodeFields(fields, values, cursor);
138→
139→            assert cursor.pos == totalSize : "cursor.pos should equal totalSize";
140→            return MemorySegment.ofArray(buf);
141→        }
142→
143→        @Override
144→        public JlsmDocument deserialize(MemorySegment segment) {
145→            Objects.requireNonNull(segment, "segment must not be null");
146→
147→            final byte[] buf = segment.toArray(ValueLayout.JAVA_BYTE);
148→            final Cursor cursor = new Cursor(buf, 0);
149→
150→            // Read header
151→            final int _ = readShortBE(buf, cursor.advance(2)) & 0xFFFF;
152→            final int writeFieldCount = readShortBE(buf, cursor.advance(2)) & 0xFFFF;
153→
154→            final List<FieldDefinition> currentFields = schema.fields();
155→            final int currentFieldCount = currentFields.size();
156→
157→            // We only read min(writeFieldCount, currentFieldCount) fields
158→            final int readCount = Math.min(writeFieldCount, currentFieldCount);
159→
160→            // Count bool fields in the *write-time* schema (same field list up to writeFieldCount)
161→            // We use the current schema's first writeFieldCount fields for the null/bool masks.
162→            // For the boolMask we count booleans among the first writeFieldCount fields.
163→            final int writeBoolCount = countBoolFieldsUpTo(currentFields, writeFieldCount);
164→            final int writeNullMaskBytes = (writeFieldCount + 7) / 8;
165→            final int writeBoolMaskBytes = writeBoolCount > 0 ? (writeBoolCount + 7) / 8 : 0;
166→
167→            final int nullMaskOffset = cursor.advance(writeNullMaskBytes);
168→            final int boolMaskOffset = writeBoolCount > 0 ? cursor.advance(writeBoolMaskBytes) : -1;
169→
170→            // Decode values
171→            final Object[] values = new Object[currentFieldCount];
172→            // Fields beyond readCount remain null (new fields added in a later schema version)
173→
174→            int boolIdx = 0; // index among BOOLEAN fields seen so far
175→            for (int i = 0; i < readCount; i++) {
176→                final FieldDefinition fd = currentFields.get(i);
177→                final boolean isNull = isNullBit(buf, nullMaskOffset, i);
178→                if (isNull) {
179→                    // Track bool index even when null
180→                    if (fd.type() == FieldType.Primitive.BOOLEAN) {
181→                        boolIdx++;
182→                    }
183→                    values[i] = null;
184→                    continue;
185→                }
186→                if (fd.type() == FieldType.Primitive.BOOLEAN) {
187→                    // Value is encoded in the bool bitmask
188→                    assert boolMaskOffset >= 0 : "bool bitmask offset should be set";
189→                    values[i] = isBoolBit(buf, boolMaskOffset, boolIdx);
190→                    boolIdx++;
191→                } else {
192→                    values[i] = decodeField(buf, cursor, fd.type());
193→                }
194→            }
195→
196→            // If writeFieldCount > currentFieldCount we need to skip the extra encoded fields.
197→            // However, since we can't know the sizes of unknown fields (their types may differ
198→            // from the current schema), we handle schema shrinkage gracefully by only reading
199→            // min(writeFieldCount, currentFieldCount). Extra write-time fields beyond the current
200→            // schema are simply ignored — the cursor position won't matter after this point.
201→
202→            return new JlsmDocument(schema, values);
203→        }
204→    }
205→
206→    // =========================================================================
207→    // Measure helpers (first pass)
208→    // =========================================================================
209→
210→    private static int measureFields(List<FieldDefinition> fields, Object[] values) {
211→        int total = 0;
212→        for (int i = 0; i < fields.size(); i++) {
213→            final FieldDefinition fd = fields.get(i);
214→            final Object val = values[i];
215→            if (val == null) {
216→                continue; // null → no value bytes
217→            }
218→            total += measureField(fd.type(), val);
219→        }
220→        return total;
221→    }
222→
223→    private static int measureField(FieldType type, Object value) {
224→        return switch (type) {
225→            case FieldType.Primitive p -> switch (p) {
226→                case STRING -> {
227→                    final byte[] utf8 = ((String) value).getBytes(StandardCharsets.UTF_8);
228→                    yield varIntSize(utf8.length) + utf8.length;
229→                }
230→                case INT8 -> 1;
231→                case INT16 -> 2;
232→                case INT32 -> 4;
233→                case INT64 -> 8;
234→                case FLOAT16 -> 2;
235→                case FLOAT32 -> 4;
236→                case FLOAT64 -> 8;
237→                case BOOLEAN -> 0; // packed in bitmask
238→                case TIMESTAMP -> 8;
239→            };
240→            case FieldType.ArrayType at -> {
241→                final Object[] arr = (Object[]) value;
242→                int sz = varIntSize(arr.length);
243→                for (Object elem : arr) {
244→                    sz += (elem == null) ? 0 : measureField(at.elementType(), elem);
245→                }
246→                yield sz;
247→            }
248→            case FieldType.ObjectType ot -> {
249→                final JlsmDocument sub = (JlsmDocument) value;
250→                final List<FieldDefinition> subFields = ot.fields();
251→                final int subBoolCount = countBoolFields(subFields);
252→                final int subNullBytes = (subFields.size() + 7) / 8;
253→                final int subBoolBytes = subBoolCount > 0 ? (subBoolCount + 7) / 8 : 0;
254→                int sz = subNullBytes + subBoolBytes;
255→                sz += measureFields(subFields, sub.values());
256→                yield sz;
257→            }
258→        };
259→    }
260→
261→    // =========================================================================
262→    // Encode helpers (second pass)
263→    // =========================================================================
264→
265→    private static void encodeFields(List<FieldDefinition> fields, Object[] values, Cursor c) {
266→        for (int i = 0; i < fields.size(); i++) {
267→            final Object val = values[i];
268→            if (val == null) {
269→                continue;
270→            }
271→            encodeField(c, fields.get(i).type(), val);
272→        }
273→    }
274→
275→    private static void encodeField(Cursor c, FieldType type, Object value) {
276→        switch (type) {
277→            case FieldType.Primitive p -> {
278→                switch (p) {
279→                    case STRING -> {
280→                        final byte[] utf8 = ((String) value).getBytes(StandardCharsets.UTF_8);
281→                        writeVarInt(c, utf8.length);
282→                        System.arraycopy(utf8, 0, c.buf, c.pos, utf8.length);
283→                        c.pos += utf8.length;
284→                    }
285→                    case INT8 -> c.buf[c.pos++] = (Byte) value;
286→                    case INT16 -> {
287→                        writeShortBE(c.buf, c.pos, (Short) value);
288→                        c.pos += 2;
289→                    }
290→                    case INT32 -> {
291→                        writeIntBE(c.buf, c.pos, (Integer) value);
292→                        c.pos += 4;
293→                    }
294→                    case INT64 -> {
295→                        writeLongBE(c.buf, c.pos, (Long) value);
296→                        c.pos += 8;
297→                    }
298→                    case FLOAT16 -> {
299→                        writeShortBE(c.buf, c.pos, (Short) value);
300→                        c.pos += 2;
301→                    }
302→                    case FLOAT32 -> {
303→                        writeIntBE(c.buf, c.pos, Float.floatToRawIntBits((Float) value));
304→                        c.pos += 4;
305→                    }
306→                    case FLOAT64 -> {
307→                        writeLongBE(c.buf, c.pos, Double.doubleToRawLongBits((Double) value));
308→                        c.pos += 8;
309→                    }
310→                    case BOOLEAN -> {
311→                        // Boolean values are packed in the bool bitmask; nothing here
312→                    }
313→                    case TIMESTAMP -> {
314→                        writeLongBE(c.buf, c.pos, (Long) value);
315→                        c.pos += 8;
316→                    }
317→                }
318→            }
319→            case FieldType.ArrayType at -> encodeArray(c, at.elementType(), (Object[]) value);
320→            case FieldType.ObjectType ot -> encodeObject(c, ot, (JlsmDocument) value);
321→        }
322→    }
323→
324→    private static void encodeArray(Cursor c, FieldType elemType, Object[] arr) {
325→        writeVarInt(c, arr.length);
326→        // SIMD-accelerated paths for contiguous numeric types
327→        if (elemType == FieldType.Primitive.INT32) {
328→            encodeInt32Array(c, arr);
329→        } else if (elemType == FieldType.Primitive.INT64) {
330→            encodeInt64Array(c, arr);
331→        } else if (elemType == FieldType.Primitive.FLOAT32) {
332→            encodeFloat32Array(c, arr);
333→        } else if (elemType == FieldType.Primitive.FLOAT64) {
334→            encodeFloat64Array(c, arr);
335→        } else {
336→            for (Object elem : arr) {
337→                if (elem != null) {
338→                    encodeField(c, elemType, elem);
339→                }
340→            }
341→        }
342→    }
343→
344→    private static void encodeObject(Cursor c, FieldType.ObjectType ot, JlsmDocument sub) {
345→        final List<FieldDefinition> subFields = ot.fields();
346→        final Object[] subValues = sub.values();
347→        final int boolCount = countBoolFields(subFields);
348→        final int nullMaskBytes = (subFields.size() + 7) / 8;
349→        final int boolMaskBytes = boolCount > 0 ? (boolCount + 7) / 8 : 0;
350→
351→        final int nullMaskStart = c.pos;
352→        c.pos += nullMaskBytes;
353→        final int boolMaskStart = boolCount > 0 ? c.pos : -1;
354→        if (boolCount > 0) {
355→            c.pos += boolMaskBytes;
356→        }
357→
358→        buildNullMask(subFields, subValues, c.buf, nullMaskStart);
359→        if (boolCount > 0) {
360→            buildBoolMask(subFields, subValues, c.buf, boolMaskStart);
361→        }
362→        encodeFields(subFields, subValues, c);
363→    }
364→
365→    // =========================================================================
366→    // SIMD encode paths
367→    // =========================================================================
368→
369→    private static void encodeInt32Array(Cursor c, Object[] arr) {
370→        final int simdLen = BYTE_SPECIES.length(); // bytes per SIMD register
371→        // Only use SIMD if we have enough data (at least one full vector worth of 4-byte ints)
372→        final int simdElems = simdLen / 4; // number of int32 elements per SIMD operation
373→        int i = 0;
374→        if (arr.length >= simdElems && simdLen >= 4) {
375→            final int[] ints = new int[simdElems];
376→            while (i + simdElems <= arr.length) {
377→                for (int j = 0; j < simdElems; j++) {
378→                    ints[j] = (Integer) arr[i + j];
379→                }
380→                // Load as bytes (little-endian native), swap to big-endian
381→                final ByteVector bv = IntVector.fromArray(IntVector.SPECIES_PREFERRED, ints, 0)
382→                        .reinterpretAsBytes();
383→                bv.rearrange(BSWAP32).intoArray(c.buf, c.pos);
384→                c.pos += simdLen;
385→                i += simdElems;
386→            }
387→        }
388→        // Scalar remainder
389→        while (i < arr.length) {
390→            writeIntBE(c.buf, c.pos, (Integer) arr[i++]);
391→            c.pos += 4;
392→        }
393→    }
394→
395→    private static void encodeInt64Array(Cursor c, Object[] arr) {
396→        final int simdLen = BYTE_SPECIES.length();
397→        final int simdElems = simdLen / 8;
398→        int i = 0;
399→        if (arr.length >= simdElems && simdLen >= 8) {
400→            final long[] longs = new long[simdElems];
401→            while (i + simdElems <= arr.length) {
402→                for (int j = 0; j < simdElems; j++) {
403→                    longs[j] = (Long) arr[i + j];
404→                }
405→                final ByteVector bv = LongVector.fromArray(LongVector.SPECIES_PREFERRED, longs, 0)
406→                        .reinterpretAsBytes();
407→                bv.rearrange(BSWAP64).intoArray(c.buf, c.pos);
408→                c.pos += simdLen;
409→                i += simdElems;
410→            }
411→        }
412→        while (i < arr.length) {
413→            writeLongBE(c.buf, c.pos, (Long) arr[i++]);
414→            c.pos += 8;
415→        }
416→    }
417→
418→    private static void encodeFloat32Array(Cursor c, Object[] arr) {
419→        final int simdLen = BYTE_SPECIES.length();
420→        final int simdElems = simdLen / 4;
421→        int i = 0;
422→        if (arr.length >= simdElems && simdLen >= 4) {
423→            final float[] floats = new float[simdElems];
424→            while (i + simdElems <= arr.length) {
425→                for (int j = 0; j < simdElems; j++) {
426→                    floats[j] = (Float) arr[i + j];
427→                }
428→                final ByteVector bv = FloatVector
429→                        .fromArray(FloatVector.SPECIES_PREFERRED, floats, 0).reinterpretAsBytes();
430→                bv.rearrange(BSWAP32).intoArray(c.buf, c.pos);
431→                c.pos += simdLen;
432→                i += simdElems;
433→            }
434→        }
435→        while (i < arr.length) {
436→            writeIntBE(c.buf, c.pos, Float.floatToRawIntBits((Float) arr[i++]));
437→            c.pos += 4;
438→        }
439→    }
440→
441→    private static void encodeFloat64Array(Cursor c, Object[] arr) {
442→        final int simdLen = BYTE_SPECIES.length();
443→        final int simdElems = simdLen / 8;
444→        int i = 0;
445→        if (arr.length >= simdElems && simdLen >= 8) {
446→            final double[] doubles = new double[simdElems];
447→            while (i + simdElems <= arr.length) {
448→                for (int j = 0; j < simdElems; j++) {
449→                    doubles[j] = (Double) arr[i + j];
450→                }
451→                final ByteVector bv = DoubleVector
452→                        .fromArray(DoubleVector.SPECIES_PREFERRED, doubles, 0).reinterpretAsBytes();
453→                bv.rearrange(BSWAP64).intoArray(c.buf, c.pos);
454→                c.pos += simdLen;
455→                i += simdElems;
456→            }
457→        }
458→        while (i < arr.length) {
459→            writeLongBE(c.buf, c.pos, Double.doubleToRawLongBits((Double) arr[i++]));
460→            c.pos += 8;
461→        }
462→    }
463→
464→    // =========================================================================
465→    // Decode helpers
466→    // =========================================================================
467→
468→    private static Object decodeField(byte[] buf, Cursor cursor, FieldType type) {
469→        return switch (type) {
470→            case FieldType.Primitive p -> switch (p) {
471→                case STRING -> {
472→                    final int len = readVarInt(buf, cursor);
473→                    final String s = new String(buf, cursor.pos, len, StandardCharsets.UTF_8);
474→                    cursor.pos += len;
475→                    yield s;
476→                }
477→                case INT8 -> buf[cursor.pos++];
478→                case INT16 -> {
479→                    final short v = readShortBE(buf, cursor.pos);
480→                    cursor.pos += 2;
481→                    yield v;
482→                }
483→                case INT32 -> {
484→                    final int v = readIntBE(buf, cursor.pos);
485→                    cursor.pos += 4;
486→                    yield v;
487→                }
488→                case INT64 -> {
489→                    final long v = readLongBE(buf, cursor.pos);
490→                    cursor.pos += 8;
491→                    yield v;
492→                }
493→                case FLOAT16 -> {
494→                    final short v = readShortBE(buf, cursor.pos);
495→                    cursor.pos += 2;
496→                    yield v;
497→                }
498→                case FLOAT32 -> {
499→                    final float v = Float.intBitsToFloat(readIntBE(buf, cursor.pos));
500→                    cursor.pos += 4;
501→                    yield v;
502→                }
503→                case FLOAT64 -> {
504→                    final double v = Double.longBitsToDouble(readLongBE(buf, cursor.pos));
505→                    cursor.pos += 8;
506→                    yield v;
507→                }
508→                case BOOLEAN ->
509→                    throw new AssertionError("BOOLEAN should be handled via bool bitmask");
510→                case TIMESTAMP -> {
511→                    final long v = readLongBE(buf, cursor.pos);
512→                    cursor.pos += 8;
513→                    yield v;
514→                }
515→            };
516→            case FieldType.ArrayType at -> decodeArray(buf, cursor, at);
517→            case FieldType.ObjectType ot -> decodeObject(buf, cursor, ot);
518→        };
519→    }
520→
521→    private static Object[] decodeArray(byte[] buf, Cursor cursor, FieldType.ArrayType at) {
522→        final int count = readVarInt(buf, cursor);
523→        // SIMD-accelerated decode for contiguous numeric types
524→        final FieldType elemType = at.elementType();
525→        if (elemType == FieldType.Primitive.INT32) {
526→            return decodeInt32Array(buf, cursor, count);
527→        } else if (elemType == FieldType.Primitive.INT64) {
528→            return decodeInt64Array(buf, cursor, count);
529→        } else if (elemType == FieldType.Primitive.FLOAT32) {
530→            return decodeFloat32Array(buf, cursor, count);
531→        } else if (elemType == FieldType.Primitive.FLOAT64) {
532→            return decodeFloat64Array(buf, cursor, count);
533→        }
534→        final Object[] arr = new Object[count];
535→        for (int i = 0; i < count; i++) {
536→            arr[i] = decodeField(buf, cursor, elemType);
537→        }
538→        return arr;
539→    }
540→
541→    private static Object decodeObject(byte[] buf, Cursor cursor, FieldType.ObjectType ot) {
542→        final List<FieldDefinition> subFields = ot.fields();
543→        final int subFieldCount = subFields.size();
544→        final int subBoolCount = countBoolFields(subFields);
545→        final int nullMaskBytes = (subFieldCount + 7) / 8;
546→        final int boolMaskBytes = subBoolCount > 0 ? (subBoolCount + 7) / 8 : 0;
547→
548→        final int nullMaskOffset = cursor.advance(nullMaskBytes);
549→        final int boolMaskOffset = subBoolCount > 0 ? cursor.advance(boolMaskBytes) : -1;
550→
551→        final Object[] subValues = new Object[subFieldCount];
552→        int boolIdx = 0;
553→        for (int i = 0; i < subFieldCount; i++) {
554→            final FieldDefinition fd = subFields.get(i);
555→            final boolean isNull = isNullBit(buf, nullMaskOffset, i);
556→            if (isNull) {
557→                if (fd.type() == FieldType.Primitive.BOOLEAN) {
558→                    boolIdx++;
559→                }
560→                subValues[i] = null;
561→                continue;
562→            }
563→            if (fd.type() == FieldType.Primitive.BOOLEAN) {
564→                assert boolMaskOffset >= 0 : "bool bitmask offset should be set";
565→                subValues[i] = isBoolBit(buf, boolMaskOffset, boolIdx);
566→                boolIdx++;
567→            } else {
568→                subValues[i] = decodeField(buf, cursor, fd.type());
569→            }
570→        }
571→
572→        // Synthesize a schema for the sub-document
573→        final JlsmSchema subSchema = ot.toSchema("nested", 0);
574→        return new JlsmDocument(subSchema, subValues);
575→    }
