577→    // =========================================================================
578→    // SIMD decode paths
579→    // =========================================================================
580→
581→    private static Object[] decodeInt32Array(byte[] buf, Cursor cursor, int count) {
582→        final Object[] result = new Object[count];
583→        final int simdLen = BYTE_SPECIES.length();
584→        final int simdElems = simdLen / 4;
585→        final int[] tmp = new int[simdElems];
586→        int i = 0;
587→        if (count >= simdElems && simdLen >= 4) {
588→            while (i + simdElems <= count) {
589→                ByteVector.fromArray(BYTE_SPECIES, buf, cursor.pos).rearrange(BSWAP32)
590→                        .reinterpretAsInts().intoArray(tmp, 0);
591→                for (int j = 0; j < simdElems; j++) {
592→                    result[i + j] = tmp[j];
593→                }
594→                cursor.pos += simdLen;
595→                i += simdElems;
596→            }
597→        }
598→        while (i < count) {
599→            result[i++] = readIntBE(buf, cursor.pos);
600→            cursor.pos += 4;
601→        }
602→        return result;
603→    }
604→
605→    private static Object[] decodeInt64Array(byte[] buf, Cursor cursor, int count) {
606→        final Object[] result = new Object[count];
607→        final int simdLen = BYTE_SPECIES.length();
608→        final int simdElems = simdLen / 8;
609→        final long[] tmp = new long[simdElems];
610→        int i = 0;
611→        if (count >= simdElems && simdLen >= 8) {
612→            while (i + simdElems <= count) {
613→                ByteVector.fromArray(BYTE_SPECIES, buf, cursor.pos).rearrange(BSWAP64)
614→                        .reinterpretAsLongs().intoArray(tmp, 0);
615→                for (int j = 0; j < simdElems; j++) {
616→                    result[i + j] = tmp[j];
617→                }
618→                cursor.pos += simdLen;
619→                i += simdElems;
620→            }
621→        }
622→        while (i < count) {
623→            result[i++] = readLongBE(buf, cursor.pos);
624→            cursor.pos += 8;
625→        }
626→        return result;
627→    }
