629→    private static Object[] decodeFloat32Array(byte[] buf, Cursor cursor, int count) {
630→        final Object[] result = new Object[count];
631→        final int simdLen = BYTE_SPECIES.length();
632→        final int simdElems = simdLen / 4;
633→        final float[] tmp = new float[simdElems];
634→        int i = 0;
635→        if (count >= simdElems && simdLen >= 4) {
636→            while (i + simdElems <= count) {
637→                ByteVector.fromArray(BYTE_SPECIES, buf, cursor.pos).rearrange(BSWAP32)
638→                        .reinterpretAsFloats().intoArray(tmp, 0);
639→                for (int j = 0; j < simdElems; j++) {
640→                    result[i + j] = tmp[j];
641→                }
642→                cursor.pos += simdLen;
643→                i += simdElems;
644→            }
645→        }
646→        while (i < count) {
647→            result[i++] = Float.intBitsToFloat(readIntBE(buf, cursor.pos));
648→            cursor.pos += 4;
649→        }
650→        return result;
651→    }
