653→    private static Object[] decodeFloat64Array(byte[] buf, Cursor cursor, int count) {
654→        final Object[] result = new Object[count];
655→        final int simdLen = BYTE_SPECIES.length();
656→        final int simdElems = simdLen / 8;
657→        final double[] tmp = new double[simdElems];
658→        int i = 0;
659→        if (count >= simdElems && simdLen >= 8) {
660→            while (i + simdElems <= count) {
661→                ByteVector.fromArray(BYTE_SPECIES, buf, cursor.pos).rearrange(BSWAP64)
662→                        .reinterpretAsDoubles().intoArray(tmp, 0);
663→                for (int j = 0; j < simdElems; j++) {
