665→                }
666→                cursor.pos += simdLen;
667→                i += simdElems;
668→            }
669→        }
670→        while (i < count) {
671→            result[i++] = Double.longBitsToDouble(readLongBE(buf, cursor.pos));
672→            cursor.pos += 8;
673→        }
674→        return result;
