781→    // =========================================================================
782→    // Primitive I/O
783→    // =========================================================================
784→
785→    private static void writeShortBE(byte[] buf, int offset, short value) {
786→        buf[offset] = (byte) (value >> 8);
787→        buf[offset + 1] = (byte) value;
788→    }
789→
790→    private static short readShortBE(byte[] buf, int offset) {
791→        return (short) ((buf[offset] << 8) | (buf[offset + 1] & 0xFF));
792→    }
793→
794→    private static void writeIntBE(byte[] buf, int offset, int value) {
795→        buf[offset] = (byte) (value >> 24);
796→        buf[offset + 1] = (byte) (value >> 16);
797→        buf[offset + 2] = (byte) (value >> 8);
798→        buf[offset + 3] = (byte) value;
799→    }
800→
801→    private static int readIntBE(byte[] buf, int offset) {
802→        return ((buf[offset] & 0xFF) << 24) | ((buf[offset + 1] & 0xFF) << 16)
803→                | ((buf[offset + 2] & 0xFF) << 8) | (buf[offset + 3] & 0xFF);
804→    }
805→
806→    private static void writeLongBE(byte[] buf, int offset, long value) {
807→        buf[offset] = (byte) (value >> 56);
808→        buf[offset + 1] = (byte) (value >> 48);
809→        buf[offset + 2] = (byte) (value >> 40);
810→        buf[offset + 3] = (byte) (value >> 32);
811→        buf[offset + 4] = (byte) (value >> 24);
812→        buf[offset + 5] = (byte) (value >> 16);
813→        buf[offset + 6] = (byte) (value >> 8);
814→        buf[offset + 7] = (byte) value;
815→    }
816→
817→    private static long readLongBE(byte[] buf, int offset) {
818→        return ((long) (buf[offset] & 0xFF) << 56) | ((long) (buf[offset + 1] & 0xFF) << 48)
819→                | ((long) (buf[offset + 2] & 0xFF) << 40) | ((long) (buf[offset + 3] & 0xFF) << 32)
820→                | ((long) (buf[offset + 4] & 0xFF) << 24) | ((long) (buf[offset + 5] & 0xFF) << 16)
821→                | ((long) (buf[offset + 6] & 0xFF) << 8) | ((long) (buf[offset + 7] & 0xFF));
822→    }
