824→    // =========================================================================
825→    // Cursor
826→    // =========================================================================
827→
828→    /** Mutable position cursor for sequential byte-array I/O. */
829→    private static final class Cursor {
830→
831→        final byte[] buf;
832→        int pos;
833→
834→        Cursor(byte[] buf, int pos) {
835→            this.buf = buf;
836→            this.pos = pos;
837→        }
838→
839→        /** Advances position by {@code n} bytes and returns the old position. */
840→        int advance(int n) {
841→            final int old = pos;
842→            pos += n;
843→            return old;
844→        }
845→    }
846→}
